INSERT INTO s503c_cards VALUES
(3010,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','matthew',22,41,$n$The King's-Son-of-David question + Tehillim 110:1 substance.$n$,$n$Matthew 22:41 — *While the Pharisees were gathered together, Yahusha (Jesus) asked them,* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) Before the oath, Yahusha (Jesus) had already put a question himself. In the temple he asked the Pharisees whose son the Messiah (Christ) is, and led them into David's psalm. At the trial he answers it from the seat itself: *sitting on the right hand of power*.$n$,17,$n$The King's-Son-of-David question + Tehillim 110:1 substance.$n$,$n$Matthew 22:41 — *While the Pharisees were gathered together.* The question put to the Pharisees opens the psalm that Yahusha (Jesus) later answers at the trial.$n$),
(3012,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','daniel',7,13,$n$*One like the Son of Adam came with the clouds of heaven* per Red Line #12.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) Daniel saw *one like the Son of Adam* come *with the clouds of heaven* and be brought to the Ancient of days. Yahusha (Jesus) says *coming in the clouds of heaven* of himself, and drops the *like*. Daniel keeps his word. The man under oath claims the name outright.$n$,17,$n$*One like the Son of Adam came with the clouds of heaven* per Red Line #12.$n$,$n$Daniel 7:13 — *one like the Son of Adam came with the clouds of heaven.* Daniel's figure is one like the Son of Adam, shown coming with the clouds to the Ancient of days.$n$),
(3014,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','luke',22,69,$n$The Lukan-parallel.$n$,$n$Luke 22:69 — *Hereafter shall the Son of Adam sit on the right hand of the power of Elohim (God).* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) Luke gives the same answer in fewer words. *Hereafter* opens it again, and the seat is *the right hand of the power*. The very next verse shows the room hearing it as a claim to be the Son of Elohim (God), and Yahusha (Jesus) does not take it back.$n$,17,$n$The Lukan-parallel.$n$,$n$Luke 22:69 — *Hereafter shall the Son of Adam sit on the right hand of the power.* Luke records the same answer about the seat, and the room takes it as a claim to be the Son of Elohim (God).$n$),
(3015,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','acts',7,55,$n$Stephen-substance sees-the-Son-of-Adam-standing-at-the-right-hand-of-Elohim.$n$,$n$Acts 7:55 — *But he, being full of the Ruach HaKodesh (Holy Spirit), looked up stedfastly into heaven, and saw the glory of Elohim (God), and Yahusha (Jesus) standing on the right hand of Elohim (God),* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) At the trial the seat was still ahead: *Hereafter shall ye see*. Stephen looks up and sees Yahusha (Jesus) *standing on the right hand of Elohim (God)*. The seat named under oath is seen taken, and in the next verse Stephen himself calls him the Son of Adam.$n$,17,$n$Stephen-substance sees-the-Son-of-Adam-standing-at-the-right-hand-of-Elohim.$n$,$n$Acts 7:55 — *and Yahusha (Jesus) standing on the right hand of Elohim (God).* Stephen sees Yahusha (Jesus) at the right hand of Elohim (God), the seat named at the trial.$n$),
(3016,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','acts',2,34,$n$Kefa's-Pesach-sermon Tehillim-110-citation.$n$,$n$Acts 2:34 — *For David is not ascended into the heavens: but he saith himself, Yahuah (LORD) said unto my Lord, Sit thou on my right hand,* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) Peter points out that David did not go up to heaven, so *Sit thou on my right hand* is not said of David. It is said to another. The psalm has two speakers, *Yahuah (LORD) said unto my Lord*, and Yahusha (Jesus) is the one who sits where the psalm sets him.$n$,17,$n$Kefa's-Pesach-sermon Tehillim-110-citation.$n$,$n$Acts 2:34 — *he saith himself, Yahuah (LORD) said unto my Lord, Sit thou on my right hand.* The psalm David spoke is the same one Yahusha (Jesus) answered with at the trial, now read as said to him.$n$),
(3017,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','romans',8,34,$n$*Christ ... is even at the right hand of Elohim.*$n$,$n$Romans 8:34 — *Who is he that condemneth? It is Messiah (Christ) that died, yea rather, that is risen again, who is even at the right hand of Elohim (God), who also maketh intercession for us.* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) Paul asks who can condemn. The high priest and the council had condemned Yahusha (Jesus) to death. Paul's answer is that the one who died is *risen again* and *at the right hand of Elohim (God)*, the seat he told them they would see.$n$,17,$n$*Christ ... is even at the right hand of Elohim.*$n$,$n$Romans 8:34 — *that is risen again, who is even at the right hand of Elohim (God).* The one condemned to death is risen and sits at the right hand of Elohim (God), as he said at the trial.$n$),
(3018,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','ephesians',1,20,$n$*Set him at his own right hand in the heavenly places.*$n$,$n$Ephesians 1:20 — *Which he wrought in Messiah (Christ), when he raised him from the dead, and set him at his own right hand in the heavenly places,* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) The man condemned at the trial is raised and set in the seat he said they would see. Paul says Elohim (God) *raised him from the dead* and put him at *his own right hand*. The council's verdict ended in death, and the seat came after it.$n$,17,$n$*Set him at his own right hand in the heavenly places.*$n$,$n$Ephesians 1:20 — *when he raised him from the dead, and set him at his own right hand.* Raised from the dead, he is set at the right hand, the place named at the trial.$n$),
(3019,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','colossians',3,1,$n$*Where Messiah sitteth on the right hand of Elohim.*$n$,$n$Colossians 3:1 — *If ye then be risen with Messiah (Christ), seek those things which are above, where Messiah (Christ) sitteth on the right hand of Elohim (God).* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) Paul points to where Messiah (Christ) *sitteth on the right hand of Elohim (God)*. That is the seat Yahusha (Jesus) told the council about. What was a warning to the high priest is now the place Paul says to look toward.$n$,17,$n$*Where Messiah sitteth on the right hand of Elohim.*$n$,$n$Colossians 3:1 — *where Messiah (Christ) sitteth on the right hand of Elohim (God).* Messiah (Christ) is seated at the right hand of Elohim (God), the seat spoken of at the trial.$n$),
(3020,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','hebrews',1,3,$n$*Sat down on the right hand of the Majesty on high* + Tehillim 110:1 citation.$n$,$n$Hebrews 1:3 — *Who being the brightness of his glory, and the express image of his person, and upholding all things by the word of his power, when he had by himself purged our sins, sat down on the right hand of the Majesty on high;* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) *Right hand of power* at the trial becomes *the right hand of the Majesty on high* here. It is the same seat under another name. The letter says he sat down after he *purged our sins*, so the seat is taken after the work is done, by the Son who is *the express image of his person*.$n$,17,$n$*Sat down on the right hand of the Majesty on high* + Tehillim 110:1 citation.$n$,$n$Hebrews 1:3 — *sat down on the right hand of the Majesty on high.* The seat Yahusha (Jesus) named under oath is described here as the right hand of the Majesty on high.$n$),
(3021,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','hebrews',1,13,$n$*Sat down on the right hand of the Majesty on high* + Tehillim 110:1 citation.$n$,$n$Hebrews 1:13 — *But to which of the angels said he at any time, Sit on my right hand, until I make thine enemies thy footstool?* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) The letter asks which angel was ever told *Sit on my right hand*, and the answer is none. The words belong to the Son. They come from the psalm Yahusha (Jesus) set before the Pharisees and then answered with at the trial, when he said he would sit at the right hand of power.$n$,17,$n$*Sat down on the right hand of the Majesty on high* + Tehillim 110:1 citation.$n$,$n$Hebrews 1:13 — *Sit on my right hand, until I make thine enemies thy footstool.* Only the Son was ever told to sit at the right hand, which is the seat he claimed at the trial.$n$),
(3024,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','hebrews',12,2,$n$*Sat down at the right hand of the throne of Elohim.*$n$,$n$Hebrews 12:2 — *Looking unto Yahusha (Jesus) the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of Elohim (God).* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) He *endured the cross, despising the shame*, and the end of it is the seat. The man who stood bound before the council is set down *at the right hand of the throne*, as he told them they would see.$n$,17,$n$*Sat down at the right hand of the throne of Elohim.*$n$,$n$Hebrews 12:2 — *and is set down at the right hand of the throne of Elohim (God).* After the cross he is set down at the right hand, the seat named before the council.$n$),
(3027,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','matthew',24,30,$n$The Son-of-Adam-coming-in-the-clouds substance per the Olivet.$n$,$n$Matthew 24:30 — *And then shall appear the sign of the Son of Adam in heaven: and then shall all the tribes of the earth mourn, and they shall see the Son of Adam coming in the clouds of heaven with power and great glory.* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) He spoke of the coming in the clouds on the mount before he spoke of it under oath. There the tribes of the earth see the Son of Adam coming *with power and great glory*. At the trial he tells the council the same sight is theirs to see. The same words, said twice.$n$,17,$n$The Son-of-Adam-coming-in-the-clouds substance per the Olivet.$n$,$n$Matthew 24:30 — *they shall see the Son of Adam coming in the clouds of heaven with power and great glory.* The coming in the clouds is spoken first to his own and then to the high priest, still ahead in both.$n$),
(3028,'canon','matthew',26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','matthew',25,31,$n$The Son-of-Adam shall-come-in-his-glory + the throne-of-his-glory.$n$,$n$Matthew 25:31 — *When the Son of Adam shall come in his glory, and all the holy angels with him, then shall he sit upon the throne of his glory:* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) The trial says sitting and coming. This verse puts both in one sentence: the Son of Adam *shall come in his glory*, and then *sit upon the throne of his glory*. The right hand of power that the high priest heard about is shown here as a throne.$n$,17,$n$The Son-of-Adam shall-come-in-his-glory + the throne-of-his-glory.$n$,$n$Matthew 25:31 — *When the Son of Adam shall come in his glory, and all the holy angels with him.* The Son of Adam comes in glory and sits on a throne, joining the coming and the sitting he named at the trial.$n$),
(6992,'canon','luke',5,24,$n$But that you may know that the Son of Adam has power upon earth to forgive sins, (he said unto the sick of the palsy,) I say unto you, Arise, and take up your couch, and go into your house.$n$,'canon','mark',2,10,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | *But that ye may know that the Son of Adam hath power upon earth to forgive sins, (he said unto the sick of the palsy,) I say unto thee, Arise, and take up thy couch, and go into thine house.* The Son-of-Adam self-identification at the paralytic-healing — *power upon earth to forgive sins* — is the same Daniyel (Daniel) 7 *Son-of-Adam* substance the King will name openly at the Sanhedrin trial.$n$,$n$Mark 2:10 — *But that ye may know that the Son of Adam hath power on earth to forgive sins, (he saith to the sick of the palsy,)* *But that you may know that the Son of Adam has power upon earth to forgive sins, (he said unto the sick of the palsy,) I say unto you, Arise, and take up your couch, and go into your house.* (Luke 5:24) At the bed of the man with palsy, Yahusha (Jesus) already speaks of himself as the Son of Adam, who *hath power on earth to forgive sins*. Long before the trial he used that name for himself. The council later hears it again with the seat and the clouds attached.$n$,17,$n$*But that ye may know that the Son of Adam hath power upon earth to forgive sins, (he said unto the sick of the palsy,) I say unto thee, Arise, and take up thy couch, and go into thine house.* The Son-of-Adam self-identification at the paralytic-healing — *power upon earth to forgive sins* — is the same Daniyel (Daniel) 7 *Son-of-Adam* substance the King will name openly at the Sanhedrin trial.$n$,$n$Mark 2:10 — *But that ye may know that the Son of Adam hath power on earth to forgive sins.* Yahusha (Jesus) called himself the Son of Adam well before the trial, where the same name carries the seat and the clouds.$n$),
(5157,'canon','mark',8,38,$n$Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.$n$,'canon','daniel',7,13,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | *When he cometh in the glory of his Father with the holy angels.* The Daniyel (Daniel) 7:13-14 Ancient-of-Days transfer-of-the-everlasting-kingdom architecture.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.* (Mark 8:38) Yahusha (Jesus) says the Son of Adam *cometh in the glory of his Father*. Daniel saw *one like the Son of Adam* brought near *before him*, the Ancient of days. There are two in the vision, one who comes and one he comes to, and the Son of Adam has a Father. Daniel's *like* stays Daniel's.$n$,17,$n$*When he cometh in the glory of his Father with the holy angels.* The Daniyel (Daniel) 7:13-14 Ancient-of-Days transfer-of-the-everlasting-kingdom architecture.$n$,$n$Daniel 7:13 — *came to the Ancient of days, and they brought him near before him.* Daniel sees one like the Son of Adam brought to the Ancient of days, one who comes and one he comes to.$n$),
(7116,'canon','luke',22,69,$n$Hereafter shall the Son of Adam sit on the right hand of the power of Elohim (God).$n$,'canon','psalms',110,1,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | *Hereafter shall the Son of Adam (son of man) sit on the right hand of the power of Elohim (God)* (Luke 22:69). The King's direct citation at the Sanhedrin trial of Tehillim (Psalm) 110:1 — *Yahuah (the LORD) said unto my Lord, Sit thou on my right hand.* The Formed-Son names his own destination at the right hand of the Formless-Father in the very moment of condemnation. The Daniyel (Daniel) 7:13-14 Son-of-Adam cloud-rider claim joined to the Tehillim 110 right-hand-session.$n$,$n$Psalm 110:1 — *Yahuah (LORD) said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool.* *Hereafter shall the Son of Adam sit on the right hand of the power of Elohim (God).* (Luke 22:69) Luke gives only the seat. The psalm gives the voice that sets it: *Yahuah (LORD) said unto my Lord*. One speaks and one sits. Yahusha (Jesus) says he is the one who will sit there, until *thine enemies* become a *footstool*.$n$,17,$n$*Hereafter shall the Son of Adam (son of man) sit on the right hand of the power of Elohim (God)* (Luke 22:69). The King's direct citation at the Sanhedrin trial of Tehillim (Psalm) 110:1 — *Yahuah (the LORD) said unto my Lord, Sit thou on my right hand.* The Formed-Son names his own destination at the right hand of the Formless-Father in the very moment of condemnation. The Daniyel (Daniel) 7:13-14 Son-of-Adam cloud-rider claim joined to the Tehillim 110 right-hand-session.$n$,$n$Psalm 110:1 — *Sit thou at my right hand, until I make thine enemies thy footstool.* The psalm's seat is the one Yahusha (Jesus) says he will take, set by one who speaks to another.$n$),
(5159,'canon','mark',8,38,$n$Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.$n$,'canon','matthew',26,64,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | The Matthean parallel of the same Sanhedrin-trial self-identification.$n$,$n$Matthew 26:64 — *Yahusha (Jesus) saith unto him, Thou hast said: nevertheless I say unto you, Hereafter shall ye see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* *Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.* (Mark 8:38) He warned that the Son of Adam would come in glory, and here he says it to the men about to condemn him. He does not hide it. *Thou hast said*, he tells the high priest, and then names the seat and the clouds.$n$,17,$n$The Matthean parallel of the same Sanhedrin-trial self-identification.$n$,$n$Matthew 26:64 — *Hereafter shall ye see the Son of Adam sitting on the right hand of power.* Yahusha (Jesus) says to the high priest what he had already said to his own, the Son of Adam seated and coming.$n$),
(5158,'canon','mark',8,38,$n$Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.$n$,'canon','mark',14,62,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | Mark 14:62 — the same Son-of-Adam-coming-in-glory named under oath at the Sanhedrin trial; the disciples hear it here first.$n$,$n$Mark 14:62 — *And Yahusha (Jesus) said, I am: and ye shall see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* *Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of Adam be ashamed, when he comes in the glory of his Father with the holy angels.* (Mark 8:38) On the road he spoke of the Son of Adam in the third person. Before the high priest he says *I am*, and the seat and the clouds follow in the same breath. The title he used of himself is now claimed plainly, under oath, in front of those who could condemn him.$n$,17,$n$Mark 14:62 — the same Son-of-Adam-coming-in-glory named under oath at the Sanhedrin trial; the disciples hear it here first.$n$,$n$Mark 14:62 — *I am: and ye shall see the Son of Adam sitting on the right hand of power.* At the trial he answers I am, and names the Son of Adam as himself.$n$),
(5325,'canon','mark',14,53,$n$And they led Yahusha (Jesus) away to the high priest: and with him were assembled all the chief priests and the elders and the scribes.$n$,'canon','psalms',110,1,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | *I am: and ye shall see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* Mark 14:62 is direct-attribution (no kaph); the kaph-preservation rule applies at Daniyel (Daniel) 7:13 alone.$n$,$n$Psalm 110:1 — *Yahuah (LORD) said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool.* *And they led Yahusha (Jesus) away to the high priest: and with him were assembled all the chief priests and the elders and the scribes.* (Mark 14:53) They led Yahusha (Jesus) to the high priest, with the chief priests, elders and scribes gathered. The psalm is the answer waiting in that room: *Sit thou at my right hand*, with *thine enemies* made a *footstool*. In that room the psalm's seat is named aloud.$n$,17,$n$*I am: and ye shall see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* Mark 14:62 is direct-attribution (no kaph); the kaph-preservation rule applies at Daniyel (Daniel) 7:13 alone.$n$,$n$Psalm 110:1 — *Sit thou at my right hand, until I make thine enemies thy footstool.* The psalm's seat is the answer Yahusha (Jesus) gives once the council is assembled.$n$),
(5326,'canon','mark',14,53,$n$And they led Yahusha (Jesus) away to the high priest: and with him were assembled all the chief priests and the elders and the scribes.$n$,'canon','daniel',7,13,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | The Daniyel (Daniel) 7:13-14 cloud-rider architecture spoken at the high priest's own question.$n$,$n$Daniel 7:13 — *I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* *And they led Yahusha (Jesus) away to the high priest: and with him were assembled all the chief priests and the elders and the scribes.* (Mark 14:53) The whole court is gathered, and the high priest's question puts Daniel's vision in the room. Daniel saw *one like the Son of Adam* and *they brought him near* the Ancient of days. The man standing before the court says the figure is himself, and he says it without the *like*.$n$,17,$n$The Daniyel (Daniel) 7:13-14 cloud-rider architecture spoken at the high priest's own question.$n$,$n$Daniel 7:13 — *one like the Son of Adam came with the clouds of heaven.* Daniel's vision of one like the Son of Adam is what the gathered council hears claimed of the man before them.$n$),
(5388,'canon','mark',16,19,$n$So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of Elohim (God).$n$,'canon','mark',14,62,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | The Sanhedrin asked who he claimed to be; the ascension answered the question in act (Mark 14:62 echo).$n$,$n$Mark 14:62 — *And Yahusha (Jesus) said, I am: and ye shall see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* *So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of Elohim (God).* (Mark 16:19) At the trial he said *ye shall see* the Son of Adam *sitting on the right hand of power*. Mark ends with him received up, and he *sat on the right hand of Elohim (God)*. The seat is no longer only promised. The book that records the promise records the taking.$n$,17,$n$The Sanhedrin asked who he claimed to be; the ascension answered the question in act (Mark 14:62 echo).$n$,$n$Mark 14:62 — *I am: and ye shall see the Son of Adam sitting on the right hand of power.* What was said at the trial about the seat is told in Mark as done.$n$),
(5390,'canon','mark',16,19,$n$So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of Elohim (God).$n$,'canon','acts',7,55,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | Acts 7:55-56's Stephen seeing the Son of Adam standing at the right hand.$n$,$n$Acts 7:55 — *But he, being full of the Ruach HaKodesh (Holy Spirit), looked up stedfastly into heaven, and saw the glory of Elohim (God), and Yahusha (Jesus) standing on the right hand of Elohim (God),* *So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of Elohim (God).* (Mark 16:19) Mark says he sat on the right hand of Elohim (God). Stephen sees it for himself, and looks up to see Yahusha (Jesus) *standing on the right hand of Elohim (God)*. One says sat and the other says standing, and the place is the same: at the right hand.$n$,17,$n$Acts 7:55-56's Stephen seeing the Son of Adam standing at the right hand.$n$,$n$Acts 7:55 — *and Yahusha (Jesus) standing on the right hand of Elohim (God).* Stephen sees Yahusha (Jesus) at the right hand, where Mark says he sat.$n$),
(5391,'canon','mark',16,19,$n$So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of Elohim (God).$n$,'canon','hebrews',1,3,$n$thread:sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth | Hebrews 1:3's *sat down on the right hand of the Majesty on high*.$n$,$n$Hebrews 1:3 — *Who being the brightness of his glory, and the express image of his person, and upholding all things by the word of his power, when he had by himself purged our sins, sat down on the right hand of the Majesty on high;* *So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of Elohim (God).* (Mark 16:19) Mark says he *sat on the right hand of Elohim (God)*. Hebrews says it again in other words: he *sat down on the right hand of the Majesty on high*, when *he had by himself purged our sins*. The same seat is told twice, once as an act and once as a name.$n$,17,$n$Hebrews 1:3's *sat down on the right hand of the Majesty on high*.$n$,$n$Hebrews 1:3 — *when he had by himself purged our sins, sat down on the right hand of the Majesty on high.* Hebrews names the seat Mark describes as the right hand of the Majesty on high.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (17, 'sanhedrin-trial-tehillim-110-and-daniel-7-self-identification-at-the-kings-own-mouth', $n$Hereafter shall ye see the Son of Adam at the right hand of power — the trial, Psalm 110 and Daniel 7 at his own mouth (Mark 14; Acts 7; Hebrews 1)$n$, $n$Hereafter shall ye see the Son of Adam at the right hand of power — the trial, Psalm 110 and Daniel 7 at his own mouth (Mark 14; Acts 7; Hebrews 1)$n$, $n$It ain't new. The high priest puts him under oath, and the answer is two scriptures:

*Yahusha (Jesus) saith unto him, Thou hast said: nevertheless I say unto you, Hereafter shall ye see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64)

Mark hears the plain word before the scriptures:

*And Yahusha (Jesus) said, I am: and ye shall see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Mark 14:62)

The seat is David's psalm:

*Yahuah (LORD) said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool.* (Psalm 110:1)

He had already set that psalm before the Pharisees in the temple and asked them a question nobody answered:

*If David then call him Adonai (Lord), how is he his son?* (Matthew 22:45)

The clouds are Daniel's:

*I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* (Daniel 7:13)

*And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* (Daniel 7:14)

Daniel says *like* the Son of Adam, because he was shown a figure who looked like a man and was more than one. At the trial the man standing in the room says it of himself without the *like*: the one Daniel saw is the one under oath, and the everlasting dominion of the next verse is his. Daniel keeps his *like*; the trial is where the name is claimed outright. The high priest understood both scriptures and what they say together:

*Then the high priest rent his clothes, saying, He hath spoken blasphemy; what further need have we of witnesses? behold, now ye have heard his blasphemy.* (Matthew 26:65)

He tore his clothes because the one at the right hand of Yahuah (the LORD), the one who comes with the clouds, had just said he was the man in front of him. He is Elohim (God) and he has a Father: the psalm has two speakers, the vision has the Ancient of days and the one brought before him, and the trial has the same two.

The seat was taken soon after. Stephen saw it, and the letters keep returning to it:

*But he, being full of the Ruach HaKodesh (Holy Spirit), looked up stedfastly into heaven, and saw the glory of Elohim (God), and Yahusha (Jesus) standing on the right hand of Elohim (God),* (Acts 7:55)

*Who being the brightness of his glory, and the express image of his person, and upholding all things by the word of his power, when he had by himself purged our sins, sat down on the right hand of the Majesty on high;* (Hebrews 1:3)

And the coming with the clouds is still ahead, said in his own words on the mount and in John's words at the opening of the Revelation, each book speaking for itself:

*And then shall appear the sign of the Son of Adam in heaven: and then shall all the tribes of the earth mourn, and they shall see the Son of Adam coming in the clouds of heaven with power and great glory.* (Matthew 24:30)

*Behold, he cometh with clouds; and every eye shall see him, and they also which pierced him: and all kindreds of the earth shall wail because of him. Even so, Amen.* (Revelation 1:7)

Two scriptures, said under oath, condemned him to death. They are the two the whole library goes on saying of him.$n$, $n$It ain't new. The high priest puts him under oath, and the answer is two scriptures:

*Yahusha (Jesus) saith unto him, Thou hast said: nevertheless I say unto you, Hereafter shall ye see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64)

Mark hears the plain word before the scriptures:

*And Yahusha (Jesus) said, I am: and ye shall see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Mark 14:62)

The seat is David's psalm:

*Yahuah (LORD) said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool.* (Psalm 110:1)

He had already set that psalm before the Pharisees in the temple and asked them a question nobody answered:

*If David then call him Adonai (Lord), how is he his son?* (Matthew 22:45)

The clouds are Daniel's:

*I saw in the night visions, and, behold, one like the Son of Adam came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him.* (Daniel 7:13)

*And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* (Daniel 7:14)

Daniel says *like* the Son of Adam, because he was shown a figure who looked like a man and was more than one. At the trial the man standing in the room says it of himself without the *like*: the one Daniel saw is the one under oath, and the everlasting dominion of the next verse is his. Daniel keeps his *like*; the trial is where the name is claimed outright. The high priest understood both scriptures and what they say together:

*Then the high priest rent his clothes, saying, He hath spoken blasphemy; what further need have we of witnesses? behold, now ye have heard his blasphemy.* (Matthew 26:65)

He tore his clothes because the one at the right hand of Yahuah (the LORD), the one who comes with the clouds, had just said he was the man in front of him. He is Elohim (God) and he has a Father: the psalm has two speakers, the vision has the Ancient of days and the one brought before him, and the trial has the same two.

The seat was taken soon after. Stephen saw it, and the letters keep returning to it:

*But he, being full of the Ruach HaKodesh (Holy Spirit), looked up stedfastly into heaven, and saw the glory of Elohim (God), and Yahusha (Jesus) standing on the right hand of Elohim (God),* (Acts 7:55)

*Who being the brightness of his glory, and the express image of his person, and upholding all things by the word of his power, when he had by himself purged our sins, sat down on the right hand of the Majesty on high;* (Hebrews 1:3)

And the coming with the clouds is still ahead, said in his own words on the mount and in John's words at the opening of the Revelation, each book speaking for itself:

*And then shall appear the sign of the Son of Adam in heaven: and then shall all the tribes of the earth mourn, and they shall see the Son of Adam coming in the clouds of heaven with power and great glory.* (Matthew 24:30)

*Behold, he cometh with clouds; and every eye shall see him, and they also which pierced him: and all kindreds of the earth shall wail because of him. Even so, Amen.* (Revelation 1:7)

Two scriptures, said under oath, condemned him to death. They are the two the whole library goes on saying of him.$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 17 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 17 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (sanhedrin-trial-tehillim-110) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — sanhedrin-trial-tehillim-110 done.'
